 function materialTexture(stone=false){const cv=document.createElement('canvas');cv.width=cv.height=256;const x=cv.getContext('2d'),im=x.createImageData(256,256);for(let y=0;y<256;y++)for(let i=0;i<256;i++){const noise=Math.sin(i*127.1+y*311.7)*43758.54,n=noise-Math.floor(noise);const v=stone?.48+n*.28:.47+.14*Math.sin(i*.6+Math.sin(y*.035)*2)+n*.15;im.data.set(stone?[v*181,v*184,v*175,255]:[v*179,v*135,v*84,255],(y*256+i)*4)}x.putImageData(im,0,0);const tx=new T.CanvasTexture(cv);tx.colorSpace=T.SRGBColorSpace;tx.wrapS=tx.wrapT=T.RepeatWrapping;return tx;}
