 function plate(parent,w,h,p,angle=0){const s=new T.Shape();s.moveTo(-w*.45,-h*.5);s.lineTo(-w*.55,h*.26);s.lineTo(-w*.2,h*.52);s.lineTo(w*.07,h*.38);s.lineTo(w*.32,h*.57);s.lineTo(w*.50,-h*.39);s.lineTo(w*.11,-h*.52);s.closePath();const o=mesh(new T.ExtrudeGeometry(s,{depth:.018,bevelEnabled:true,bevelSize:.004,bevelThickness:.003,bevelSegments:1,steps:1}),mats.bark,p,parent);o.rotation.z=angle;o.userData.plate=true;return o;}
