 const held={pickaxe:makePickaxe(),hammer:makeHammer(),spear:makeSpear()};for(const [id,o]of Object.entries(held)){o.name='Workshop_Held_'+id;o.visible=false;game.scene.add(o)}
 const armor=makeArmor();armor.name='Workshop_Worn_Armor';armor.visible=false;game.scene.add(armor);let wearing=false,attackState=null,lastAttack=-10,currentTime=0;
 const baseArmor=armor.userData.sections.map(o=>({o,home:o.position.clone()}));
 function world(b){return b.getWorldPosition(V())}const boneCache=new Map();function find(name){if(!boneCache.get(name))boneCache.set(name,c.localBone(tfp.visibleRoot,name)||null);return boneCache.get(name)}
