 const api={handRig:{armIK:c.armIK,palmReference:c.palmReference,applyGrip:c.applyRealGrip},posePickaxe,pickaxeProps,recipes,items:W.items,held,armor,makeProps,pose,canStart,nearbyLog,updateMenu,updateHeld,attack,beginSpear,releaseSpear,cancelSpear,get charging(){return chargeStart!==null},get charge(){return chargeProgress()},get attackActive(){return !!attackState||chargeStart!==null},get armorEquipped(){return wearing},equipArmor,damageMultiplier:()=>wearing?.75:1,destroy,constructors,materials:mats};buildMenu();window.gamePrimitive=api;return api;
